1	import React, { useCallback, useEffect, useRef, useState } from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import {
4	    submitOracleCommandStream,
5	    submitOracleCommand,
6	    subscribeOracleCommandState,
7	    type OracleCommandState
8	} from '../../lib/oracleCommandBridge';
9	import { apiFetch } from '../../lib/runtime';
10	import VisualSynthesisLane from './VisualSynthesisLane';
11	import OracleToolOrbs from './OracleToolOrbs';
12	import OracleTerminal from './OracleTerminal';
13	
14	interface ChatMessage {
15	    id: string;
16	    role: 'user' | 'nexus';
17	    content: string;
18	    streaming?: boolean;
19	    timestamp: string;
20	    files?: UploadedFile[];
21	}
22	
23	interface UploadedFile {
24	    name: string;
25	    type: string;
26	    dataUrl: string;
27	    size: number;
28	}
29	
30	interface ImageModel {
31	    id: string;
32	    label: string;
33	    provider: string;
34	}
35	
36	type TabId = 'context' | 'research' | 'code' | 'visual' | 'ops';
37	
38	const TABS: { id: TabId; label: string; icon: string }[] = [
39	    { id: 'context', label: 'Context',  icon: '◈' },
40	    { id: 'research', label: 'Research', icon: '◎' },
41	    { id: 'code',    label: 'Code',     icon: '⬡' },
42	    { id: 'visual',  label: 'Visual',   icon: '◆' },
43	    { id: 'ops',     label: 'Ops',      icon: '◉' }
44	];
45	
46	const REASONING_LEVELS = ['low', 'medium', 'high', 'council'] as const;
47	type ReasoningLevel = typeof REASONING_LEVELS[number];
48	
49	const REASONING_COLORS: Record<ReasoningLevel, string> = {
50	    low:     'var(--text-dim)',
51	    medium:  'var(--cyan-glow)',
52	    high:    'var(--gold-solar)',
53	    council: 'var(--red-fusion)'
54	};
55	
56	export default function OraclePage() {
57	    const [messages, setMessages] = useState<ChatMessage[]>([{
58	        id: 'boot',
59	        role: 'nexus',
60	        content: 'NEXUS — Oracle online. All systems nominal. What directive shall I process?',
61	        timestamp: new Date().toISOString()
62	    }]);
63	    const [input, setInput]           = useState('');
64	    const [activeTab, setActiveTab]   = useState<TabId>('context');
65	    const [reasoning, setReasoning]   = useState<ReasoningLevel>('medium');
66	    const [terminalOpen, setTerminalOpen] = useState(false);
67	    const [dragOver, setDragOver]     = useState(false);
68	    const [pendingFiles, setPendingFiles] = useState<UploadedFile[]>([]);
69	    const [isListening, setIsListening] = useState(false);
70	    const [imageModels, setImageModels] = useState<{ kie: ImageModel[]; remote: ImageModel[] }>({ kie: [], remote: [] });
71	    const [oracleState, setOracleState] = useState<OracleCommandState | null>(null);
72	    const [models, setModels]          = useState<any[]>([]);
73	    const [selectedModel, setSelectedModel] = useState<string>('qwen-liberated:latest');
74	
75	    const chatEndRef   = useRef<HTMLDivElement>(null);
76	    const fileInputRef = useRef<HTMLInputElement>(null);
77	    const recognitionRef = useRef<any>(null);
78	
79	    // Subscribe to oracle state
80	    useEffect(() => {
81	        return subscribeOracleCommandState(setOracleState);
82	    }, []);
83	
84	    // Auto-scroll chat
85	    useEffect(() => {
86	        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
87	    }, [messages]);
88	
89	    // Load models + image model catalog
90	    useEffect(() => {
91	        apiFetch('/api/neural/models').then(r => r.json()).then(d => { if (Array.isArray(d)) setModels(d); }).catch(() => {});
92	        apiFetch('/api/neural/images/models').then(r => r.json()).then(d => { if (d && Array.isArray(d.kie) && Array.isArray(d.remote)) setImageModels(d); }).catch(() => {});
93	    }, []);
94	
95	    const addMessage = useCallback((msg: ChatMessage) => {
96	        setMessages(prev => [...prev, msg]);
97	    }, []);
98	
99	    const updateLastNexus = useCallback((patch: Partial<ChatMessage>) => {
100	        setMessages(prev => {
101	            const idx = [...prev].reverse().findIndex(m => m.role === 'nexus');
102	            if (idx === -1) return prev;
103	            const realIdx = prev.length - 1 - idx;
104	            return prev.map((m, i) => i === realIdx ? { ...m, ...patch } : m);
105	        });
106	    }, []);
107	
108	    const handleSubmit = useCallback(async () => {
109	        const cmd = input.trim();
110	        if (!cmd && pendingFiles.length === 0) return;
111	        setInput('');
112	
113	        const userMsg: ChatMessage = {
114	            id: `u-${Date.now()}`,
115	            role: 'user',
116	            content: cmd || '[file upload]',
117	            timestamp: new Date().toISOString(),
118	            files: pendingFiles.length > 0 ? [...pendingFiles] : undefined
119	        };
120	        addMessage(userMsg);
121	        setPendingFiles([]);
122	
123	        const nexusId = `n-${Date.now()}`;
124	        addMessage({ id: nexusId, role: 'nexus', content: '', streaming: true, timestamp: new Date().toISOString() });
125	
126	        const useCouncil = reasoning === 'council';
127	
128	        if (!useCouncil) {
129	            // Streaming path — near-realtime
130	            try {
131	                await submitOracleCommandStream({
132	                    command: cmd || 'describe uploaded files',
133	                    source: 'typed',
134	                    modelId: selectedModel,
135	                    onChunk: (chunk) => {
136	                        if (chunk.type === 'token') {
137	                            setMessages(prev => prev.map(m =>
138	                                m.id === nexusId
139	                                    ? { ...m, content: m.content + (chunk.token || ''), streaming: true }
140	                                    : m
141	                            ));
142	                        } else if (chunk.type === 'done') {
143	                            setMessages(prev => prev.map(m =>
144	                                m.id === nexusId
145	                                    ? { ...m, content: chunk.content || m.content, streaming: false }
146	                                    : m
147	                            ));
148	                        } else if (chunk.type === 'error') {
149	                            setMessages(prev => prev.map(m =>
150	                                m.id === nexusId
151	                                    ? { ...m, content: `[Oracle error: ${chunk.error}]`, streaming: false }
152	                                    : m
153	                            ));
154	                        }
155	                    }
156	                });
157	            } catch (err: any) {
158	                updateLastNexus({ content: `[Stream failed: ${err.message}]`, streaming: false });
159	            }
160	        } else {
161	            // Council mode — blocking with phase display
162	            try {
163	                const result = await submitOracleCommand({
164	                    command: cmd,
165	                    source: 'typed',
166	                    useCouncil: true
167	                });
168	                const content = result?.response || result?.content || JSON.stringify(result);
169	                updateLastNexus({ content: String(content), streaming: false });
170	            } catch (err: any) {
171	                updateLastNexus({ content: `[Council error: ${err.message}]`, streaming: false });
172	            }
173	        }
174	    }, [input, pendingFiles, reasoning, selectedModel, addMessage, updateLastNexus]);
175	
176	    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
177	        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmit(); }
178	    }, [handleSubmit]);
179	
180	    const handleFileDrop = useCallback((files: FileList | null) => {
181	        if (!files) return;
182	        const allowed = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp',
183	            'text/markdown', 'text/plain', 'application/x-python', 'text/x-python'];
184	        Array.from(files).forEach(file => {
185	            if (!allowed.some(t => file.type === t || file.name.endsWith('.md') || file.name.endsWith('.py') || file.name.endsWith('.ts'))) return;
186	            const reader = new FileReader();
187	            reader.onload = () => {
188	                setPendingFiles(prev => [...prev, {
189	                    name: file.name,
190	                    type: file.type,
191	                    dataUrl: reader.result as string,
192	                    size: file.size
193	                }]);
194	            };
195	            reader.readAsDataURL(file);
196	        });
197	    }, []);
198	
199	    const toggleVoice = useCallback(() => {
200	        const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
201	        if (!SR) return;
202	        if (isListening) {
203	            recognitionRef.current?.stop();
204	            setIsListening(false);
205	            return;
206	        }
207	        const rec = new SR();
208	        rec.lang = 'en-US';
209	        rec.continuous = false;
210	        rec.onresult = (e: any) => {
211	            const text: string = e.results[0]?.[0]?.transcript || '';
212	            setInput(prev => (prev + ' ' + text).trim());
213	            setIsListening(false);
214	        };
215	        rec.onend = () => setIsListening(false);
216	        rec.start();
217	        recognitionRef.current = rec as any;
218	        setIsListening(true);
219	    }, [isListening]);
220	
221	    const cycleReasoning = useCallback(() => {
222	        setReasoning(prev => {
223	            const idx = REASONING_LEVELS.indexOf(prev);
224	            return REASONING_LEVELS[(idx + 1) % REASONING_LEVELS.length];
225	        });
226	    }, []);
227	
228	    const isBusy = ['submitted', 'deliberating', 'stale'].includes(oracleState?.phase ?? '');
229	
230	    return (
231	        <div className="oracle-page" onDragOver={e => { e.preventDefault(); setDragOver(true); }}
232	            onDragLeave={() => setDragOver(false)}
233	            onDrop={e => { e.preventDefault(); setDragOver(false); handleFileDrop(e.dataTransfer.files); }}
234	        >
235	            {/* Drop overlay */}
236	            <AnimatePresence>
237	                {dragOver && (
238	                    <motion.div className="oracle-drop-overlay"
239	                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
240	                        <span>Drop files into NEXUS</span>
241	                    </motion.div>
242	                )}
243	            </AnimatePresence>
244	
245	            {/* Main layout */}
246	            <div className="oracle-layout">
247	
248	                {/* LEFT — Category tabs */}
249	                <div className="oracle-tabs">
250	                    {TABS.map(tab => (
251	                        <button key={tab.id} className={`oracle-tab ${activeTab === tab.id ? 'active' : ''}`}
252	                            onClick={() => setActiveTab(tab.id)}>
253	                            <span className="tab-icon">{tab.icon}</span>
254	                            <span className="tab-label">{tab.label}</span>
255	                            {tab.id === 'visual' && (imageModels.kie.length > 0 || imageModels.remote.length > 0) && (
256	                                <span className="tab-ready-dot" title="Image models loaded"/>
257	                            )}
258	                        </button>
259	                    ))}
260	                    <div className="oracle-tab-spacer"/>
261	                    <button className="oracle-tab terminal-toggle" onClick={() => setTerminalOpen(p => !p)}>
262	                        <span className="tab-icon">_</span>
263	                        <span className="tab-label">Terminal</span>
264	                    </button>
265	                </div>
266	
267	                {/* CENTER — Chat + orbs */}
268	                <div className="oracle-center">
269	
270	                    {/* Tool orbs or tab content */}
271	                    <div className="oracle-content-area">
272	                        {activeTab === 'visual' ? (
273	                            <VisualSynthesisLane models={imageModels} />
274	                        ) : (
275	                            <OracleToolOrbs activeTab={activeTab} />
276	                        )}
277	                    </div>
278	
279	                    {/* Chat thread */}
280	                    <div className="oracle-chat">
281	                        <div className="oracle-messages">
282	                            {messages.map(msg => (
283	                                <motion.div key={msg.id} className={`oracle-msg oracle-msg--${msg.role}`}
284	                                    initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
285	                                    transition={{ duration: 0.2 }}>
286	                                    <span className="msg-label">
287	                                        {msg.role === 'user' ? 'NEXUS' : 'ORACLE'}
288	                                    </span>
289	                                    <div className="msg-body">
290	                                        {msg.content}
291	                                        {msg.streaming && <span className="cursor-blink">▋</span>}
292	                                    </div>
293	                                    {msg.files && msg.files.length > 0 && (
294	                                        <div className="msg-files">
295	                                            {msg.files.map((f, i) => (
296	                                                <span key={i} className="msg-file-pill">{f.name}</span>
297	                                            ))}
298	                                        </div>
299	                                    )}
300	                                </motion.div>
301	                            ))}
302	                            {isBusy && (
303	                                <div className="oracle-phase-indicator">
304	                                    <span className="phase-dot"/>
305	                                    {oracleState?.phase} · {oracleState?.elapsedMs ? Math.floor(oracleState.elapsedMs / 1000) + 's' : '...'}
306	                                </div>
307	                            )}
308	                            <div ref={chatEndRef}/>
309	                        </div>
310	
311	                        {/* Pending file pills */}
312	                        {pendingFiles.length > 0 && (
313	                            <div className="oracle-pending-files">
314	                                {pendingFiles.map((f, i) => (
315	                                    <span key={i} className="pending-file-pill">
316	                                        {f.name}
317	                                        <button onClick={() => setPendingFiles(p => p.filter((_, j) => j !== i))}>×</button>
318	                                    </span>
319	                                ))}
320	                            </div>
321	                        )}
322	
323	                        {/* Input bar */}
324	                        <div className="oracle-input-bar">
325	                            {/* Plus — file picker */}
326	                            <button className="input-action input-plus" onClick={() => fileInputRef.current?.click()} title="Attach file">
327	                                +
328	                            </button>
329	                            <input ref={fileInputRef} type="file" multiple hidden
330	                                accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.md,.py,.ts,.txt"
331	                                onChange={e => handleFileDrop(e.target.files)}/>
332	
333	                            <textarea
334	                                className="oracle-textarea"
335	                                value={input}
336	                                onChange={e => setInput(e.target.value)}
337	                                onKeyDown={handleKeyDown}
338	                                placeholder="Ask NEXUS..."
339	                                rows={1}
340	                            />
341	
342	                            {/* Model selector */}
343	                            <select className="oracle-model-select" value={selectedModel}
344	                                onChange={e => setSelectedModel(e.target.value)}>
345	                                {models.length > 0
346	                                    ? models.map((m: any) => <option key={m.id} value={m.id}>{m.name || m.id}</option>)
347	                                    : <option value="qwen-liberated:latest">Qwen Local</option>}
348	                            </select>
349	
350	                            {/* Reasoning level */}
351	                            <button className="input-action reasoning-level"
352	                                style={{ color: REASONING_COLORS[reasoning] }}
353	                                onClick={cycleReasoning}
354	                                title={`Reasoning: ${reasoning}`}>
355	                                {reasoning.slice(0, 3).toUpperCase()}
356	                            </button>
357	
358	                            {/* Mic */}
359	                            <button className={`input-action input-mic ${isListening ? 'active' : ''}`}
360	                                onClick={toggleVoice} title="Voice input">
361	                                {isListening ? '◉' : '🎤'}
362	                            </button>
363	
364	                            {/* Send */}
365	                            <button className="input-action input-send" onClick={handleSubmit} disabled={isBusy}>
366	                                {isBusy ? '⟳' : '↑'}
367	                            </button>
368	                        </div>
369	                    </div>
370	                </div>
371	            </div>
372	
373	            {/* Terminal pane (collapsible) */}
374	            <AnimatePresence>
375	                {terminalOpen && (
376	                    <motion.div className="oracle-terminal-pane"
377	                        initial={{ height: 0 }} animate={{ height: 320 }} exit={{ height: 0 }}
378	                        transition={{ duration: 0.25 }}>
379	                        <OracleTerminal />
380	                    </motion.div>
381	                )}
382	            </AnimatePresence>
383	
384	            <style>{ORACLE_STYLES}</style>
385	        </div>
386	    );
387	}
388	
389	const ORACLE_STYLES = `
390	.oracle-page {
391	  display: flex;
392	  flex-direction: column;
393	  height: 100%;
394	  background: var(--bg-void);
395	  color: var(--silver-albedo);
396	  font-family: 'JetBrains Mono', 'Fira Code', monospace;
397	  position: relative;
398	  overflow: hidden;
399	}
400	
401	.oracle-drop-overlay {
402	  position: absolute;
403	  inset: 0;
404	  background: rgba(159,232,115,0.08);
405	  border: 2px dashed var(--cyan-glow);
406	  z-index: 100;
407	  display: flex;
408	  align-items: center;
409	  justify-content: center;
410	  font-size: 1.4rem;
411	  color: var(--cyan-glow);
412	  letter-spacing: 0.12em;
413	}
414	
415	.oracle-layout {
416	  display: flex;
417	  flex: 1;
418	  overflow: hidden;
419	  min-height: 0;
420	}
421	
422	/* LEFT TABS */
423	.oracle-tabs {
424	  display: flex;
425	  flex-direction: column;
426	  width: 88px;
427	  border-right: 1px solid rgba(159,232,115,0.12);
428	  padding: 8px 0;
429	  gap: 2px;
430	  flex-shrink: 0;
431	}
432	
433	.oracle-tab {
434	  display: flex;
435	  flex-direction: column;
436	  align-items: center;
437	  gap: 4px;
438	  padding: 10px 4px;
439	  background: none;
440	  border: none;
441	  color: var(--text-dim);
442	  cursor: pointer;
443	  font-family: inherit;
444	  font-size: 9px;
445	  letter-spacing: 0.08em;
446	  text-transform: uppercase;
447	  border-left: 2px solid transparent;
448	  transition: all 0.15s;
449	}
450	.oracle-tab:hover { color: var(--cyan-glow); background: rgba(159,232,115,0.04); }
451	.oracle-tab.active {
452	  color: var(--cyan-glow);
453	  border-left-color: var(--cyan-glow);
454	  background: rgba(159,232,115,0.06);
455	}
456	.oracle-tab.terminal-toggle { color: var(--gold-solar); margin-top: auto; }
457	.tab-icon { font-size: 14px; }
458	.oracle-tab-spacer { flex: 1; }
459	
460	/* CENTER */
461	.oracle-center {
462	  display: flex;
463	  flex-direction: column;
464	  flex: 1;
465	  overflow: hidden;
466	  min-width: 0;
467	}
468	
469	.oracle-content-area {
470	  flex: 0 0 260px;
471	  border-bottom: 1px solid rgba(159,232,115,0.1);
472	  overflow-y: auto;
473	  padding: 12px;
474	}
475	
476	/* CHAT */
477	.oracle-chat {
478	  display: flex;
479	  flex-direction: column;
480	  flex: 1;
481	  overflow: hidden;
482	  min-height: 0;
483	}
484	
485	.oracle-messages {
486	  flex: 1;
487	  overflow-y: auto;
488	  padding: 12px 16px;
489	  display: flex;
490	  flex-direction: column;
491	  gap: 10px;
492	}
493	
494	.oracle-msg { display: flex; flex-direction: column; gap: 3px; max-width: 90%; }
495	.oracle-msg--user { align-self: flex-end; }
496	.oracle-msg--nexus { align-self: flex-start; }
497	
498	.msg-label {
499	  font-size: 9px;
500	  letter-spacing: 0.12em;
501	  text-transform: uppercase;
502	  opacity: 0.45;
503	}
504	.oracle-msg--user .msg-label  { color: var(--cyan-glow); text-align: right; }
505	.oracle-msg--nexus .msg-label { color: var(--gold-solar); }
506	
507	.msg-body {
508	  background: rgba(255,255,255,0.04);
509	  border: 1px solid rgba(159,232,115,0.1);
510	  border-radius: 2px;
511	  padding: 8px 12px;
512	  font-size: 13px;
513	  line-height: 1.6;
514	  white-space: pre-wrap;
515	  word-break: break-word;
516	}
517	.oracle-msg--user .msg-body {
518	  background: rgba(159,232,115,0.06);
519	  border-color: rgba(159,232,115,0.2);
520	}
521	
522	.cursor-blink {
523	  animation: blink 0.8s step-end infinite;
524	  color: var(--cyan-glow);
525	}
526	@keyframes blink { 50% { opacity: 0; } }
527	
528	.msg-files { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
529	.msg-file-pill {
530	  font-size: 10px;
531	  padding: 2px 8px;
532	  background: rgba(159,232,115,0.1);
533	  border: 1px solid rgba(159,232,115,0.2);
534	  border-radius: 2px;
535	  color: var(--cyan-glow);
536	}
537	
538	.oracle-phase-indicator {
539	  display: flex;
540	  align-items: center;
541	  gap: 8px;
542	  font-size: 11px;
543	  color: var(--gold-solar);
544	  opacity: 0.7;
545	  padding: 0 4px;
546	}
547	.phase-dot {
548	  width: 6px; height: 6px;
549	  border-radius: 50%;
550	  background: var(--gold-solar);
551	  animation: pulseDot 1s ease-in-out infinite;
552	}
553	@keyframes pulseDot { 0%,100% { opacity: 1; } 50% { opacity: 0.3; } }
554	
555	/* PENDING FILES */
556	.oracle-pending-files {
557	  display: flex;
558	  flex-wrap: wrap;
559	  gap: 6px;
560	  padding: 6px 16px;
561	  border-top: 1px solid rgba(159,232,115,0.08);
562	}
563	.pending-file-pill {
564	  display: flex;
565	  align-items: center;
566	  gap: 6px;
567	  font-size: 11px;
568	  padding: 3px 8px;
569	  background: rgba(118,185,0,0.1);
570	  border: 1px solid rgba(118,185,0,0.3);
571	  border-radius: 2px;
572	  color: var(--gold-solar);
573	}
574	.pending-file-pill button {
575	  background: none; border: none; color: var(--red-fusion);
576	  cursor: pointer; font-size: 13px; padding: 0; line-height: 1;
577	}
578	
579	/* INPUT BAR */
580	.oracle-input-bar {
581	  display: flex;
582	  align-items: flex-end;
583	  gap: 8px;
584	  padding: 10px 16px;
585	  border-top: 1px solid rgba(159,232,115,0.12);
586	  background: rgba(8,8,8,0.6);
587	}
588	
589	.oracle-textarea {
590	  flex: 1;
591	  background: rgba(255,255,255,0.03);
592	  border: 1px solid rgba(159,232,115,0.15);
593	  border-radius: 2px;
594	  color: var(--silver-albedo);
595	  font-family: inherit;
596	  font-size: 13px;
597	  padding: 8px 10px;
598	  resize: none;
599	  outline: none;
600	  min-height: 36px;
601	  max-height: 120px;
602	  line-height: 1.5;
603	  transition: border-color 0.15s;
604	}
605	.oracle-textarea:focus { border-color: rgba(159,232,115,0.4); }
606	.oracle-textarea::placeholder { color: var(--text-dim); opacity: 0.5; }
