39	                ? 'LOW'
40	                : escalated
41	                    ? 'GUARDED'
42	                    : risk === 'HIGH'
43	                        ? 'LOW'
44	                        : risk === 'MEDIUM'
45	                            ? 'MEDIUM'
46	                            : 'HIGH';
47	
48	            return {
49	                runtime: String(runtime || decision?.preferredRuntime || routingDecision.preferredRuntime || 'local').toUpperCase(),
50	                risk,
51	                escalated,
52	                loopCount: extras.loopCount || 1,
53	                disagreement: escalated || risk === 'HIGH' || status === 'FORGE_DEGRADED',
54	                confidenceBand,
55	                heartbeat: status === 'FORGE_DEGRADED'
56	                    ? 'DEGRADED'
57	                    : status === 'CONCLAVE_TIMEOUT'
