88	                            allowCloud: false,
89	                            retrievalProfile: routingDecision.retrievalProfile
90	                        }
91	                    );
92	                }
93	
94	                return {
95	                    status: response.status || 'CONCLAVE_SUCCESS',
96	                    final_summary: response.final_summary || response.content || 'Directive processed.',
97	                    content: response.content || response.final_summary || 'Directive processed.',
98	                    model: response.model,
99	                    timestamp: response.timestamp,
