25	            ? { limit: limitOrOptions }
26	            : limitOrOptions;
27	
28	        const limit = options.limit || 5;
29	        const profile = options.profile;
30	
31	        console.log(`⬡ VECTOR_SEARCH :: Query: "${query}" :: profile=${profile || 'DEFAULT'}`);
32	
33	        const queryVector = await neuralForge.getEmbedding(query);
34	        if (!queryVector) {
35	            console.error('⬡ VECTOR_SEARCH_ERROR :: Failed to generate query embedding.');
36	            return [];
37	        }
38	
39	        const nodes = db.prepare('SELECT * FROM knowledge_nodes WHERE embedding IS NOT NULL').all() as KnowledgeNode[];
40	        if (nodes.length === 0) {
41	            console.warn('⬡ VECTOR_SEARCH_WARNING :: No embedded nodes found in DB.');
42	            return [];
43	        }
44	
45	        const filteredNodes = nodes.filter((node) => this.matchesProfile(node, profile));
46	        const scoredNodes = filteredNodes.map((node) => {
47	            const nodeVector = JSON.parse(node.embedding!);
48	            const similarity = this.cosineSimilarity(queryVector, nodeVector);
49	            const weightedScore = similarity * this.profileWeight(node, profile);
50	            return { ...node, similarity: weightedScore };
51	        });
52	
53	        return scoredNodes
54	            .sort((a, b) => b.similarity - a.similarity)
55	            .slice(0, limit);
56	    }
