58	    private matchesProfile(node: KnowledgeNode, profile?: RetrievalProfile) {
59	        if (!profile) return true;
60	
61	        const sourcePath = node.source_path || '';
62	        const domain = node.domain || '';
63	
64	        if (profile === 'IC2M_OPERATIONS') {
65	            return sourcePath.startsWith('iC2M/')
66	                || sourcePath.startsWith('06_NETWORK-SYNC/C2MOVIEZ/')
67	                || domain === 'PROJECT_ENGINE'
68	                || domain === 'CLAUDIO_VAULT';
69	        }
70	
71	        if (profile === 'NUDIMMUD_SYSTEM') {
72	            return sourcePath.startsWith('backend/')
73	                || sourcePath.startsWith('_SYSTEM/')
74	                || sourcePath.startsWith('NISABA/')
75	                || sourcePath.startsWith('NEURAL-NETWORK/')
76	                || sourcePath.startsWith('00_COMMAND-CENTER/')
77	                || ['SYSTEM', 'NEURAL', 'COMMAND', 'DEPLOYMENT', 'INGESTION', 'SWARM', 'DEFENSE', 'QUALITY'].includes(domain);
78	        }
79	
80	        return sourcePath.startsWith('iC2M/')
81	            || sourcePath.startsWith('06_NETWORK-SYNC/C2MOVIEZ/')
82	            || sourcePath.startsWith('backend/')
83	            || sourcePath.startsWith('_SYSTEM/')
84	            || sourcePath.startsWith('00_COMMAND-CENTER/');
85	    }
86	
87	    private profileWeight(node: KnowledgeNode, profile?: RetrievalProfile) {
88	        if (!profile) return 1;
89	
90	        const sourcePath = node.source_path || '';
91	        const domain = node.domain || '';
92	
93	        if (profile === 'IC2M_OPERATIONS') {
94	            if (sourcePath.startsWith('iC2M/')) return 1.35;
95	            if (sourcePath.startsWith('06_NETWORK-SYNC/C2MOVIEZ/')) return 1.25;
96	            if (domain === 'PROJECT_ENGINE' || domain === 'CLAUDIO_VAULT') return 1.2;
97	            return 0.8;
98	        }
99	
100	        if (profile === 'NUDIMMUD_SYSTEM') {
101	            if (sourcePath.startsWith('backend/')) return 1.35;
102	            if (sourcePath.startsWith('_SYSTEM/') || sourcePath.startsWith('NISABA/')) return 1.25;
103	            if (sourcePath.startsWith('00_COMMAND-CENTER/') || sourcePath.startsWith('NEURAL-NETWORK/')) return 1.15;
104	            if (domain === 'SYSTEM' || domain === 'NEURAL' || domain === 'COMMAND') return 1.1;
105	            return 0.75;
106	        }
107	
108	        if (sourcePath.startsWith('iC2M/') || sourcePath.startsWith('06_NETWORK-SYNC/C2MOVIEZ/')) return 1.15;
109	        if (sourcePath.startsWith('backend/') || sourcePath.startsWith('_SYSTEM/')) return 1.15;
110	        return 1;
111	    }
112	
113	    /**
114	     * Basic Cosine Similarity calculation
115	     */
116	    private cosineSimilarity(vecA: number[], vecB: number[]): number {
117	        let dotProduct = 0;
118	        let normA = 0;
119	        let normB = 0;
120	        for (let i = 0; i < vecA.length; i++) {
121	            dotProduct += vecA[i] * vecB[i];
122	            normA += vecA[i] * vecA[i];
123	            normB += vecB[i] * vecB[i];
124	        }
125	        if (normA === 0 || normB === 0) return 0;
126	        return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
127	    }
128	}
