173	            runtimeAuthToken = undefined;
174	        }
175	
176	        const authToken = await resolveRuntimeAuthToken();
177	        const requestInit = withAuthHeader(init, authToken);
178	        let lastError: unknown;
179	
180	        for (const origin of API_ORIGINS) {
