183	            } catch (error) {
184	                lastError = error;
185	            }
186	        }
187	
188	        throw lastError;
189	    };
190	
191	    const response = await attemptRequest(false);
192	    if (response.status !== 401) {
193	        return response;
194	    }
195	
196	    return attemptRequest(true);
197	}
